using System;using System.Collections.Generic;using System.Drawing;using System.Drawing.Drawing2D;using System.Windows.Forms;using ScoreModern.RecoveredFragments;
namespace ScoreModern {
 public sealed class NativeOverview {
  public short X,Y,Divisor;public float Factor;public readonly short Left,Top,Right,Bottom;
  public NativeOverview(short x,short y,short divisor,float factor,short left,short top,short right,short bottom){X=x;Y=y;Divisor=divisor;Factor=factor;Left=left;Top=top;Right=right;Bottom=bottom;}
  static short W(int n){return unchecked((short)n);}static short Bound(short value,short limit){return (short)Math.Max(-limit,Math.Min(limit,value));}
  // Original overlay23:0879..0984, signed word subtraction and clamping.
  public List<PrimitiveTextPoint> Outline(){short limit=(short)(32760/Divisor);short l=Bound(W(Left-X),limit),r=Bound(W(Right-X),limit),t=Bound(W(Y-Top),limit),b=Bound(W(Y-Bottom),limit);short[] xx={l,l,r,r,l},yy={t,b,b,t,t};var points=new List<PrimitiveTextPoint>();for(int n=0;n<5;n++)points.Add(new PrimitiveTextPoint{X=W(xx[n]*Divisor),Y=W(yy[n]*Divisor),Operation=(short)(n==0?1:0)});return points;}
  public bool Key(Keys key){switch(key){case Keys.Up:Y=W(Y+5);break;case Keys.Down:Y=W(Y-5);break;case Keys.Left:X=W(X+5);break;case Keys.Right:X=W(X-5);break;case Keys.PageUp:Y=W(Y+100);break;case Keys.PageDown:Y=W(Y-100);break;case Keys.Tab:case Keys.F10:X=W(X-50);break;case Keys.Shift|Keys.Tab:case Keys.F9:X=W(X+50);break;case Keys.Alt|Keys.Y:Y=W(Y+20);break;case Keys.Alt|Keys.B:Y=W(Y-20);break;case Keys.Alt|Keys.G:X=W(X+20);break;case Keys.Alt|Keys.H:X=W(X-20);break;default:return false;}return true;}
  public byte[] Plane(Canvas canvas){var raster=new NativeDosRaster(96,96,153,191,0,479,true);var dat=NativeDatDrawing.Get(canvas.Library);var cache=new NativeDatHeadCache();short font=0;foreach(var item in canvas.Score.Items){if(canvas.DisplayHidden(item))continue;short next;raster.Draw(NativeDatDrawing.Prepare(item,canvas.PageDocument.Contexts[item],canvas.PageDocument,canvas.Library,canvas.TextLayout,dat,cache,font,out next));font=next;}foreach(var item in canvas.Score.Items)if(item.Code==8&&item.Staff==1&&!canvas.DisplayHidden(item))raster.Draw(NativeScanStructuralVectors.ScreenGuide(item,canvas.PageDocument));foreach(var number in canvas.TextLayout.ShowActualDatFonts?new NativeDosOverlays.NumberPlan[0]:NativeDosOverlays.Numbers(canvas.Score,canvas.PageDocument,canvas.TextLayout,canvas.DisappearingStaffs))raster.Draw(number.Points);
   // Original DS:33B2..33BA /33CA..33D2 retained page-frame arrays.
   short[] pageX={-1500,31500,31500,-1500,-1500},pageY={16500,16500,-26500,-26500,16500};var page=new List<PrimitiveTextPoint>();for(int n=0;n<5;n++)page.Add(new PrimitiveTextPoint{X=pageX[n],Y=pageY[n],Operation=(short)(n==0?1:0)});raster.Draw(page);raster.Draw(Outline());return raster.Plane;}
 }
 public sealed partial class Editor {
  NativeOverview scoreOverview;Panel overviewPanel;Bitmap overviewImage;
  void BeginOverview(){if(mode==ScreenMode.Print&&UsesOriginalPrintMenu||musicInput!=null||canvas.Score==null||mode==ScreenMode.Edit&&!NativeKeyboardOptions.EditOverview)return;canvas.LayoutScore();scoreOverview=new NativeOverview(NativeDosViewport.OriginX,NativeDosViewport.OriginY,NativeDosViewport.Divisor,NativeDosViewport.ZoomFactor,1,canvas.DosClipTop,638,canvas.DosClipBottom);overviewPanel=new Panel{Dock=DockStyle.Fill,BackColor=Color.White,TabStop=true};overviewPanel.Paint+=(sender,e)=>{if(overviewImage==null)return;float scale=Math.Min(overviewPanel.ClientSize.Width/640f,overviewPanel.ClientSize.Height/480f);var rect=new RectangleF((overviewPanel.ClientSize.Width-640*scale)/2,(overviewPanel.ClientSize.Height-480*scale)/2,640*scale,480*scale);e.Graphics.InterpolationMode=InterpolationMode.NearestNeighbor;e.Graphics.PixelOffsetMode=PixelOffsetMode.Half;e.Graphics.DrawImage(overviewImage,rect);};Controls.Add(overviewPanel);overviewPanel.BringToFront();overviewPanel.Focus();try{RefreshOverview();}catch{DisposeOverview();throw;}}
  void RefreshOverview(){byte[] plane=scoreOverview.Plane(canvas);var bitmap=new Bitmap(640,480,System.Drawing.Imaging.PixelFormat.Format32bppArgb);var bits=bitmap.LockBits(new Rectangle(0,0,640,480),System.Drawing.Imaging.ImageLockMode.WriteOnly,System.Drawing.Imaging.PixelFormat.Format32bppArgb);try{byte[] pixels=new byte[bits.Stride*480];for(int y=0;y<480;y++)for(int x=0;x<640;x++){int at=y*bits.Stride+x*4;byte color=(plane[y*80+x/8]&(128>>(x%8)))!=0?(byte)0:(byte)255;pixels[at]=pixels[at+1]=pixels[at+2]=color;pixels[at+3]=255;}System.Runtime.InteropServices.Marshal.Copy(pixels,0,bits.Scan0,pixels.Length);}finally{bitmap.UnlockBits(bits);}if(overviewImage!=null)overviewImage.Dispose();overviewImage=bitmap;overviewPanel.Invalidate();}
  void DisposeOverview(){scoreOverview=null;if(overviewPanel!=null){Controls.Remove(overviewPanel);overviewPanel.Dispose();overviewPanel=null;}if(overviewImage!=null){overviewImage.Dispose();overviewImage=null;}}
  bool OverviewKey(Keys keys){if(scoreOverview==null||keys==(Keys.Alt|Keys.F4))return false;if(keys==Keys.Enter||keys==Keys.Escape||keys==Keys.Space||keys==(Keys.Alt|Keys.S)){var overview=scoreOverview;DisposeOverview();if(overview.X==NativeDosViewport.OriginX&&overview.Y==NativeDosViewport.OriginY){canvas.Invalidate();command.Focus();return true;}ApplyMouseCamera(()=>{NativeDosViewport.OriginX=overview.X;NativeDosViewport.OriginY=overview.Y;NativeDosViewport.Divisor=overview.Divisor;NativeDosViewport.ZoomFactor=overview.Factor;NativeDosViewport.DisplayChanged();});command.Focus();return true;}if(scoreOverview.Key(keys))RefreshOverview();return true;}
 }
